import { createContext, ForwardedRef, RefObject } from 'react';

import { MouseCoordinate } from '../types/overlays.js';

export type OverlaysContextProps = {
  mousePosition?: MouseCoordinate;
  eventLocalPoint?: MouseCoordinate;
  chartBounds?: DOMRect;
  isInChartBounds: boolean;
  tooltipContainerRef?: ForwardedRef<HTMLDivElement>;
  overlayRef?: RefObject<SVGRectElement | HTMLDivElement>;
};

export const OverlaysContext: React.Context<OverlaysContextProps> =
  createContext<OverlaysContextProps>({
    isInChartBounds: false,
  });
